<?php view('calls-assets'); ?><div class="heading"><h2>مدیریت فراخوان‌ها</h2><a class="primary" href="<?= e(url('admin',['tab'=>'calls','new'=>1])) ?>">ایجاد فراخوان</a></div><form method="get" class="call-search"><input type="hidden" name="page" value="admin"><input type="hidden" name="tab" value="calls"><input name="q" aria-label="جست‌وجوی فراخوان" placeholder="جست‌وجوی فراخوان…" value="<?= e($_GET['q']??'') ?>"><select name="status" aria-label="وضعیت"><option value="">همه وضعیت‌ها</option><?php foreach(['draft'=>'پیش‌نویس','published'=>'منتشرشده','paused'=>'توقف نمایش عمومی','archived'=>'بایگانی'] as $v=>$l): ?><option value="<?= $v ?>" <?= ($_GET['status']??'')===$v?'selected':'' ?>><?= $l ?></option><?php endforeach ?></select><button class="outline">اعمال</button></form>
<div class="call-admin-cards"><?php foreach($result['items'] as $r): ?><article class="panel"><h3><?= e($r['title']) ?></h3><p><?= e($r['status']) ?> · پایان دریافت: <?= e($r['end_at']?:'تعیین نشده') ?></p><div class="call-actions"><a class="primary" href="<?= e(url('admin',['tab'=>'calls','edit'=>$r['id']])) ?>">تعریف، بخش‌ها و فرم‌ها</a><a class="outline" href="<?= e(url('admin',['tab'=>'submissions','call_id'=>$r['id']])) ?>">آثار این فراخوان</a><?php if($r['status']==='published'): ?><a class="outline" target="_blank" rel="noopener" href="<?= e(url('call',['id'=>$r['id']])) ?>">صفحه عمومی</a><?php endif ?></div></article><?php endforeach ?></div><?php if(!$result['items']): ?><p class="empty">فراخوانی ثبت نشده است.</p><?php endif ?><?php view('public-pagination',['count'=>$result['count'],'per'=>$result['per'],'page'=>$result['page'],'route'=>'admin','filters'=>['tab'=>'calls','q'=>$_GET['q']??'','status'=>$_GET['status']??'']]); ?>